// aim.cpp
// World-to-screen projection + smoothed crosshair delta inside a 240 px cone.
//
// Build (standalone smoke test):
//   cl /std:c++17 /DAIM_SMOKE /O2 /W4 aim.cpp /Fe:aim_test.exe
//
// Exported helpers:
//   WorldToScreen   – projects a 3-D world position to 2-D screen coords
//   GetAimDelta     – returns a smoothed XY delta toward the nearest in-cone entity head

#define WIN32_LEAN_AND_MEAN
#include <windows.h>
#include <cmath>
#include <cstdint>
#include <optional>
#include <vector>

// ---------------------------------------------------------------------------
// Types
// ---------------------------------------------------------------------------

struct Vec3 {
    float x, y, z;
};

struct Vec2 {
    float x, y;
};

// Column-major 4x4 view-projection matrix (matches D3D/OpenGL row convention;
// swap the index arithmetic below if your engine uses row-major storage).
struct Matrix4 {
    float m[4][4];
};

struct Entity {
    Vec3  headPos;      // world-space head bone position
    bool  alive;        // skip dead / invalid entries
};

// Output of GetAimDelta
struct AimDelta {
    float dx;           // pixels to move crosshair right (+) or left (-)
    float dy;           // pixels to move crosshair down  (+) or up   (-)
    bool  hasTarget;    // false when no entity falls inside the cone
};

// ---------------------------------------------------------------------------
// WorldToScreen
//
// Projects `worldPos` through `vp` (combined view * projection matrix) and
// maps the result to [0, screenW] x [0, screenH] pixel coordinates.
// Returns false when the point is behind the camera (w <= 0).
// ---------------------------------------------------------------------------
bool WorldToScreen(
    const Vec3&    worldPos,
    const Matrix4& vp,
    int            screenW,
    int            screenH,
    Vec2&          outScreen)
{
    // Multiply by the 4x4 matrix (treating world pos as a homogeneous point).
    float clipX = worldPos.x * vp.m[0][0] + worldPos.y * vp.m[1][0] +
                  worldPos.z * vp.m[2][0] +             vp.m[3][0];
    float clipY = worldPos.x * vp.m[0][1] + worldPos.y * vp.m[1][1] +
                  worldPos.z * vp.m[2][1] +             vp.m[3][1];
    float clipW = worldPos.x * vp.m[0][3] + worldPos.y * vp.m[1][3] +
                  worldPos.z * vp.m[2][3] +             vp.m[3][3];

    if (clipW <= 0.0f)
        return false;   // behind the near plane

    float ndcX = clipX / clipW;   // [-1, 1]
    float ndcY = clipY / clipW;   // [-1, 1]  (Y points up in clip space)

    outScreen.x = ( ndcX + 1.0f) * 0.5f * static_cast<float>(screenW);
    outScreen.y = (-ndcY + 1.0f) * 0.5f * static_cast<float>(screenH);
    return true;
}

// ---------------------------------------------------------------------------
// GetAimDelta
//
// Scans `entities`, projects each alive head to screen, discards anything
// outside the 240 px circle centred on the crosshair, picks the closest
// remaining target, then returns a smoothed step toward it.
//
// Parameters:
//   entities    – flat list of entities to consider
//   vp          – current view-projection matrix
//   screenW/H   – viewport dimensions in pixels
//   smoothing   – [0,1] lerp factor applied each call; lower = slower/smoother
//                 (typical range 0.05 – 0.30)
//
// The function keeps an internal velocity accumulator (static) for
// cross-frame smoothing so the caller only needs to add the returned delta
// to the current cursor/aim position.
// ---------------------------------------------------------------------------
AimDelta GetAimDelta(
    const std::vector<Entity>& entities,
    const Matrix4&             vp,
    int                        screenW,
    int                        screenH,
    float                      smoothing = 0.15f)
{
    constexpr float kConeRadius    = 240.0f;   // px
    constexpr float kConeRadiusSq  = kConeRadius * kConeRadius;

    // Crosshair sits at screen centre.
    const float cx = static_cast<float>(screenW) * 0.5f;
    const float cy = static_cast<float>(screenH) * 0.5f;

    // Find the closest entity head inside the cone.
    float bestDistSq = kConeRadiusSq;
    std::optional<Vec2> bestScreen;

    for (const auto& ent : entities) {
        if (!ent.alive)
            continue;

        Vec2 sp{};
        if (!WorldToScreen(ent.headPos, vp, screenW, screenH, sp))
            continue;

        float dx = sp.x - cx;
        float dy = sp.y - cy;
        float dSq = dx * dx + dy * dy;

        if (dSq < bestDistSq) {
            bestDistSq = dSq;
            bestScreen = sp;
        }
    }

    if (!bestScreen.has_value()) {
        // Decay velocity toward zero when there is no target.
        static float velX = 0.0f, velY = 0.0f;
        velX *= (1.0f - smoothing);
        velY *= (1.0f - smoothing);
        return { velX, velY, false };
    }

    // Raw delta from crosshair to target head.
    float rawDx = bestScreen->x - cx;
    float rawDy = bestScreen->y - cy;

    // Exponential-smoothing velocity accumulator (persists across calls).
    static float velX = 0.0f, velY = 0.0f;
    velX = velX + (rawDx - velX) * smoothing;
    velY = velY + (rawDy - velY) * smoothing;

    return { velX, velY, true };
}

// ---------------------------------------------------------------------------
// Smoke test – compiled only when DAIM_SMOKE is defined.
// ---------------------------------------------------------------------------
#ifdef AIM_SMOKE
#include <cstdio>

int main()
{
    // Minimal orthographic-style VP matrix that maps world coords 1:1.
    Matrix4 vp{};
    vp.m[0][0] = 1.0f;
    vp.m[1][1] = 1.0f;
    vp.m[2][2] = 1.0f;
    vp.m[3][3] = 1.0f;

    const int W = 1920, H = 1080;

    // One entity with its head 50 px right of centre, projected via identity.
    // For the identity VP the NDC trick needs an entity at NDC coords; instead
    // set up a proper clip-space entity so WorldToScreen maps correctly.
    // We'll use a simple perspective VP manually:
    //   entity at world (0.052, 0, -1) => screenX ~ cx+50, screenY ~ cy
    // For simplicity just place two entities and check the nearest is chosen.
    std::vector<Entity> ents;
    ents.push_back({ {  50.0f, -20.0f, 0.0f }, true });   // inside  cone
    ents.push_back({ { 300.0f,  300.0f, 0.0f }, true });   // outside cone

    // Build a VP that maps world x/y directly to NDC with w=1 so that
    // WorldToScreen gives pixel = (world + 1) * 0.5 * screen.
    // Set m[3][0]=0, m[3][1]=0, m[3][3]=1, rest zero except diagonal.
    Matrix4 testVP{};
    // We want: clipX = x * (2/W), clipY = y * (2/H), clipW = 1
    testVP.m[0][0] = 2.0f / static_cast<float>(W);
    testVP.m[1][1] = 2.0f / static_cast<float>(H);  // Y up in clip; negated in W2S
    testVP.m[2][2] = 1.0f;
    testVP.m[3][3] = 1.0f;

    // Entity at world (50, 20, 0):
    //   clipX = 50 * (2/1920) = 0.052, clipW = 1
    //   ndcX  = 0.052  => screenX = (0.052+1)*0.5*1920 = 1010 (cx+50)
    //   ndcY  = 0.021  => screenY = (-0.021+1)*0.5*1080 = 528  (cy-11)
    Vec2 sp{};
    bool ok = WorldToScreen({ 50.0f, 20.0f, 0.0f }, testVP, W, H, sp);
    printf("WorldToScreen test: ok=%d  x=%.1f (want ~1010) y=%.1f (want ~528)\n",
           (int)ok, sp.x, sp.y);

    std::vector<Entity> ents2;
    ents2.push_back({ {  50.0f,  20.0f, 0.0f }, true });   // ~50 px right, ~11 px up
    ents2.push_back({ { 500.0f, 500.0f, 0.0f }, true });   // far outside cone

    for (int i = 0; i < 5; ++i) {
        AimDelta d = GetAimDelta(ents2, testVP, W, H, 0.3f);
        printf("frame %d: dx=%.3f  dy=%.3f  hasTarget=%d\n",
               i, d.dx, d.dy, (int)d.hasTarget);
    }

    return 0;
}
#endif // AIM_SMOKE
